from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class SmsMethods(BaseClient):
    """
    Методы группы 'Смс' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=31)
    @tracer.start_as_current_span("sms.rapi_sendNotifySms")
    def rapi_sendNotifySms(self, smsNotifyContext: str):
        """
        При помощи этого метода происходит отправка смс,
        если ранее клиент получил ивент suggestToNotifyUser,
        с smsNotifyContext.
        :param smsNotifyContext:
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/sendNotifySms",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"smsNotifyContext": smsNotifyContext},
            },
        )
